from collections import deque

x = [3, 1, 4, 1, 5]
k = 2
dq, out = deque(), []           # dq holds indices, values decreasing
for i, v in enumerate(x):
    while dq and x[dq[-1]] <= v:
        dq.pop()                # smaller values can never win again
    dq.append(i)
    if dq[0] <= i - k:
        dq.popleft()            # front fell out of the window
    if i >= k - 1:
        out.append(x[dq[0]])
print(out)                       # window maxima of size 2

